// Fixed provider recovery composites. Original-fault mode does not inject or
// relabel another case's fault. This lane never dispatches business work.
export const LC_PROVIDER_VECTORS=Object.freeze({LC06:['accepted-response-lost','same-job-reconciled'],LC07:['stale-revision','exact-restoration']});
export function validateLcProviderSelection(c,s){
 exact(c,['schema','caseId','mode','sourceCommit','candidateDigest','workspaceId','projectId','serviceId','connection','original','deadlineAt','maxNativeCalls','maxProviderCalls',...(c.caseId==='LC06'?['fault']:['definition'])]);
 assert.equal(c.schema,'runtime-lc-provider-selection/v1');assert(LC_PROVIDER_VECTORS[c.caseId]);assert.deepEqual(s.caseIds,[c.caseId]);assert.equal(s.phase,'PRE_RELEASE');assert.equal(c.sourceCommit,s.sourceCommit);assert.equal(c.candidateDigest,'sha256:'+s.expectedManifestDigest);assert.equal(c.mode,c.caseId==='LC06'?'ORIGINAL_FAULT':'ORIGINAL_ACTIVATION');
 for(const k of ['workspaceId','projectId','serviceId'])assert(typeof c[k]==='string'&&c[k].length>0);
 for(const k of ['connection','original',c.caseId==='LC06'?'fault':'definition']){exact(c[k],['ref','sha256']);assert(path.isAbsolute(c[k].ref)&&/^[a-f0-9]{64}$/.test(c[k].sha256));}
 assert(Number.isFinite(Date.parse(c.deadlineAt)));for(const k of ['maxNativeCalls','maxProviderCalls'])assert(Number.isSafeInteger(c[k])&&c[k]>0&&c[k]<=300);return c;
}

export function lcProviderInstanceIdentity(i){return{id:i.id,definitionRevisionId:i.pins.definitionRevisionId,pins:i.pins,pinsDigest:i.pinsDigest,createdAt:i.createdAt,requestIds:i.requestIds,stages:Object.fromEntries(Object.entries(i.stages).map(([k,v])=>[k,{requestId:v.requestId,inputDigest:v.inputDigest,attempts:v.attempts}]))};}
export function projectLc07Variables(raw,status,expected){
 // Never put an unexpected provider variable, parser excerpt or assertion diff
 // into an artifact/error. Only exact locally-known ciInputs may leave here.
 try{const rows=JSON.parse(raw),keys=Object.keys(expected);if(status!==200||!Array.isArray(rows)||rows.length!==keys.length)throw Error();
  for(const key of keys){const matches=rows.filter(v=>v&&v.key===key);if(matches.length!==1||matches[0].value!==expected[key]||matches[0].variable_type!=='env_var')throw Error();}
  return{rows:keys.map(key=>({key,value:expected[key],variable_type:'env_var'})),evidence:{verified:true,count:keys.length,rawDigest:sha(raw)}};
 }catch{throw Error('NOT_READY: exact original CI variables unavailable');}
}
export function assertLcProviderPrincipal(expected,current,authorize,projectId){assert(current&&stable(current)===stable(expected),'NOT_READY: original principal changed');authorize(current,projectId,'read');return current;}
